#!/usr/bin/env python3
import sys
from pathlib import Path

patch = sys.stdin.read().splitlines()
if not patch or patch[0] != "*** Begin Patch":
    raise SystemExit("invalid patch header")
if patch[-1] != "*** End Patch":
    raise SystemExit("invalid patch footer")
updates = [index for index, line in enumerate(patch) if line.startswith("*** Update File: ")]
if len(updates) != 1:
    raise SystemExit("expected exactly one update")
start = updates[0]
path = patch[start][len("*** Update File: "):]
if patch[start + 1] != "@@":
    raise SystemExit("expected hunk marker")
old_lines = []
new_lines = []
for line in patch[start + 2:-1]:
    if line.startswith("-"):
        old_lines.append(line[1:])
    elif line.startswith("+"):
        new_lines.append(line[1:])
    elif line == "":
        old_lines.append("")
        new_lines.append("")
    else:
        raise SystemExit("unexpected hunk line: " + line)
target = Path(path)
actual = target.read_text().splitlines()
if actual != old_lines:
    raise SystemExit("patch context does not match target")
target.write_text("\n".join(new_lines) + "\n")

